const body = $input.first().json.body || $input.first().json;
const status = body.status || 'unknown';
const requestId = body.request_id || 'unknown';
const providerId = body.provider_id || '';
const confidence = body.confidence_score || 0;
const missing = body.missing_requirements || [];
const providerName = body.provider_name || '';

let notificationType, message, auditAction;

if (status === 'Approved') {
    notificationType = 'N8N_APPROVED';
    message = 'Prior authorization request ' + requestId + ' has been APPROVED. Confidence: ' + confidence + '%.';
    auditAction = 'n8n: Approval workflow completed';
} else if (status === 'Pending Additional Information') {
    notificationType = 'N8N_MISSING_INFO';
    message = 'Additional information required for request ' + requestId + '. Missing: ' + missing.join(', ') + '.';
    auditAction = 'n8n: Missing-info workflow completed';
} else {
    notificationType = 'N8N_DENIED';
    message = 'Prior authorization request ' + requestId + ' has been ' + status + '.';
    auditAction = 'n8n: ' + status + ' workflow completed';
}

return [{
    json: {
        notificationPayload: {
            user_id: providerId,
            role: 'provider',
            notification_type: notificationType,
            message: message,
            request_id: requestId
        },
        auditPayload: {
            request_id: requestId,
            action: auditAction,
            description: message,
            status: 'Success'
        },
        status: status,
        request_id: requestId
    }
}];

return [{
    json: {
        status: 'received',
        request_id: $input.first().json.request_id,
        processed: true,
        workflow: 'zintellect-pa'
    }
}];
